const { email, results } = $input.first().json.body;

const rows = results.map((r, i) => {
  const medal = ['🥇', '🥈', '🥉'][i] || '📍';
  return `
    <tr>
      <td style="padding:12px 0;border-bottom:1px solid #eee;">
        <div style="font-size:18px;">${medal} <strong>${r.name}, ${r.country}</strong> — ${r.match}% match</div>
        <div style="color:#555;margin:6px 0;">${r.description}</div>
        <div style="font-size:13px;color:#777;">Best time: ${r.best_time} · Budget: ${r.budget_estimate} · Stay: ${r.recommended_stay}</div>
      </td>
    </tr>`;
}).join('');

const html = `
  <div style="font-family:sans-serif;max-width:560px;margin:0 auto;">
    <h2>✈️ Your TravelMatch recommendations</h2>
    <table style="width:100%;border-collapse:collapse;">${rows}</table>
  </div>`;

return [{ json: { email, html } }];
